starter.exercise.h:
/* Original C17 port of the MIT-licensed Exercism Python exercise.
 * Heap-allocated return values belong to the caller; release with free() or
 * the matching destroy/free function. Inputs and labels are borrowed unless
 * an initializer explicitly copies them. Initialize state structs to zero.
 * Caller output arrays must fit the complete result: at most the input element
 * count (flatten: all integer leaves), rows*columns (boards), 512 (Sudoku),
 * tree node count (paths), target/minimum_coin (change), or interval count+1 / 12
 * (scales). String outputs without a size argument need strlen(input)+strlen(input)/5+1
 * bytes for cipher encode, strlen(input)+1 for decode, and rows/4*(columns/3+1)+1 for
 * OCR.
 */
#ifndef EXERCISE_H
#define EXERCISE_H
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
/* Every zipper owns an independent immutable snapshot. Navigation and edits
 * return new zippers; they never change their input or the source tree.
 * Missing children / root.up return a zipper whose focus is NULL.
 * Release each returned snapshot exactly once with zipper_free().
 * Plain struct assignment is a shallow ownership transfer, not a clone: do
 * not free both copies. Use zipper_clone() for an independently owned copy. */
typedef struct tree {
    int value;
    struct tree *left, *right;
} tree;
typedef struct {
    tree *root, *focus;
    tree **ancestors;
    size_t depth;
} zipper;
zipper zipper_from_tree(const tree *root);
zipper zipper_clone(const zipper *source);
zipper zipper_left(const zipper *z);
zipper zipper_right(const zipper *z);
zipper zipper_up(const zipper *z);
int zipper_value(const zipper *z);
zipper zipper_set_value(const zipper *z, int value);
zipper zipper_set_left(const zipper *z, const tree *subtree);
zipper zipper_set_right(const zipper *z, const tree *subtree);
const tree *zipper_to_tree(const zipper *z);
void zipper_free(zipper *z);

#endif

